export interface ProfitEntry {
  id: string;
  worker: string;
  direction: string;
  stage: string;
  amount: number;
  percentage: number;
  country: string;
  workerShare: number;
  irlShare: number;
  payoutStatus: 'Paid' | 'Pending';
  date: string;
  mentor: string;
  mentorPercentage: number;
  mentorAmount: number;
  referralStatus: boolean;
  referralAmount: number;
  totalPayout: number;
  finalIrlShare: number;
}

export interface SummaryStats {
  totalRevenue: number;
  totalWorkerPayouts: number;
  totalMentorPayouts: number;
  totalIrlShare: number;
  totalEntries: number;
}

import { GoogleGenAI } from "@google/genai";
import { ProfitEntry } from "../types";

export const analyzeTeamPerformance = async (entries: ProfitEntry[]): Promise<string> => {
  if (entries.length === 0) return "No data available for analysis yet.";

  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

  const simplifiedData = entries.map(e => ({
    worker: e.worker,
    dir: e.direction,
    amt: e.amount,
    date: e.date,
    mentor: e.mentor
  }));

  const prompt = `Analyze this team profit data and provide a concise (max 200 words) strategic summary. 
  Identify top performers, most profitable directions, and any concerns about mentor distribution or volume trends. 
  Keep it professional and motivating for a TG (Telegram) team owner.

  Data: ${JSON.stringify(simplifiedData)}`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        thinkingConfig: { thinkingBudget: 0 }
      }
    });
    return response.text || "Failed to generate analysis.";
  } catch (error) {
    console.error("Gemini analysis error:", error);
    return "AI analysis is currently unavailable. Check API configuration.";
  }
};

