import React, { useState, useEffect } from 'react';
import { ProfitEntry } from '../types';

interface ProfitFormProps {
  onAdd: (entry: ProfitEntry) => void;
  onClose: () => void;
}

export const ProfitForm: React.FC<ProfitFormProps> = ({ onAdd, onClose }) => {
  const [formData, setFormData] = useState<Omit<ProfitEntry, 'id' | 'workerShare' | 'irlShare' | 'mentorAmount' | 'totalPayout' | 'finalIrlShare'>>({
    worker: '',
    direction: '',
    stage: 'Pending',
    amount: 0,
    percentage: 70,
    country: '',
    payoutStatus: 'Pending',
    date: new Date().toISOString().split('T')[0],
    mentor: '',
    mentorPercentage: 10,
    referralStatus: false,
    referralAmount: 0,
  });

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value, type } = e.target;
    const val = type === 'checkbox' ? (e.target as HTMLInputElement).checked : value;
    setFormData(prev => ({
      ...prev,
      [name]: type === 'number' ? parseFloat(value) || 0 : val
    }));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    // Calculations
    const workerShareRaw = (formData.amount * formData.percentage) / 100;
    const irlShareRaw = formData.amount - workerShareRaw;
    const mentorAmt = formData.mentor ? (workerShareRaw * formData.mentorPercentage) / 100 : 0;
    const totalPay = workerShareRaw - mentorAmt - (formData.referralStatus ? formData.referralAmount : 0);
    const finalIrl = irlShareRaw + mentorAmt + (formData.referralStatus ? formData.referralAmount : 0);

    const newEntry: ProfitEntry = {
      ...formData,
      id: Math.random().toString(36).substr(2, 9),
      workerShare: workerShareRaw,
      irlShare: irlShareRaw,
      mentorAmount: mentorAmt,
      totalPayout: totalPay,
      finalIrlShare: finalIrl
    };

    onAdd(newEntry);
    onClose();
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm p-4">
      <div className="bg-slate-900 border border-slate-700 rounded-xl w-full max-w-2xl shadow-2xl overflow-hidden">
        <div className="bg-slate-800 px-6 py-4 flex justify-between items-center border-b border-slate-700">
          <h2 className="text-xl font-bold text-white">Добавить новый профит</h2>
          <button onClick={onClose} className="text-slate-400 hover:text-white">&times;</button>
        </div>

        <form onSubmit={handleSubmit} className="p-6 grid grid-cols-1 md:grid-cols-2 gap-4 max-h-[80vh] overflow-y-auto custom-scrollbar">
          <div className="space-y-1">
            <label className="text-xs font-semibold text-slate-400 uppercase">Воркер (TG)</label>
            <input name="worker" required value={formData.worker} onChange={handleChange} className="w-full bg-slate-800 border border-slate-700 rounded p-2 focus:ring-2 focus:ring-blue-500 outline-none" placeholder="nick_tg" />
          </div>

          <div className="space-y-1">
            <label className="text-xs font-semibold text-slate-400 uppercase">Направление</label>
            <input name="direction" required value={formData.direction} onChange={handleChange} className="w-full bg-slate-800 border border-slate-700 rounded p-2 focus:ring-2 focus:ring-blue-500 outline-none" placeholder="NFT / Crypto" />
          </div>

          <div className="space-y-1">
            <label className="text-xs font-semibold text-slate-400 uppercase">Сумма ($)</label>
            <input name="amount" type="number" required value={formData.amount} onChange={handleChange} className="w-full bg-slate-800 border border-slate-700 rounded p-2 focus:ring-2 focus:ring-emerald-500 outline-none" />
          </div>

          <div className="space-y-1">
            <label className="text-xs font-semibold text-slate-400 uppercase">Процент воркера (%)</label>
            <input name="percentage" type="number" value={formData.percentage} onChange={handleChange} className="w-full bg-slate-800 border border-slate-700 rounded p-2 focus:ring-2 focus:ring-blue-500 outline-none" />
          </div>

          <div className="space-y-1">
            <label className="text-xs font-semibold text-slate-400 uppercase">Страна</label>
            <input name="country" value={formData.country} onChange={handleChange} className="w-full bg-slate-800 border border-slate-700 rounded p-2 outline-none" placeholder="Russia / Poland" />
          </div>

          <div className="space-y-1">
            <label className="text-xs font-semibold text-slate-400 uppercase">Статус выплаты</label>
            <select name="payoutStatus" value={formData.payoutStatus} onChange={handleChange} className="w-full bg-slate-800 border border-slate-700 rounded p-2 outline-none">
              <option value="Pending">В ожидании</option>
              <option value="Paid">Выплачено</option>
            </select>
          </div>

          <div className="border-t border-slate-700 col-span-full my-2"></div>

          <div className="space-y-1">
            <label className="text-xs font-semibold text-slate-400 uppercase">Наставник (TG)</label>
            <input name="mentor" value={formData.mentor} onChange={handleChange} className="w-full bg-slate-800 border border-slate-700 rounded p-2 outline-none" placeholder="@mentor_nick" />
          </div>

          <div className="space-y-1">
            <label className="text-xs font-semibold text-slate-400 uppercase">% Наставника (от доли воркера)</label>
            <input name="mentorPercentage" type="number" value={formData.mentorPercentage} onChange={handleChange} className="w-full bg-slate-800 border border-slate-700 rounded p-2 outline-none" />
          </div>

          <div className="flex items-center space-x-2 pt-6">
            <input type="checkbox" name="referralStatus" checked={formData.referralStatus} onChange={handleChange} className="w-4 h-4 rounded bg-slate-800 border-slate-700" />
            <label className="text-sm font-semibold text-slate-300">Реферал был?</label>
