          <div className="space-y-1">
            <label className="text-xs font-semibold text-slate-400 uppercase">Сумма реферала ($)</label>
            <input name="referralAmount" type="number" disabled={!formData.referralStatus} value={formData.referralAmount} onChange={handleChange} className="w-full bg-slate-800 border border-slate-700 rounded p-2 outline-none disabled:opacity-50" />
          </div>

          <div className="col-span-full mt-6 flex justify-end space-x-3">
