            <button type="submit" className="px-8 py-2 rounded-lg font-bold bg-blue-600 hover:bg-blue-500 text-white shadow-lg transition-transform active:scale-95">Сохранить</button>
          </div>
        </form>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { ProfitEntry, SummaryStats } from './types';
import { ProfitTable } from './components/ProfitTable';
import { ProfitForm } from './components/ProfitForm';
import { analyzeTeamPerformance } from './services/geminiService';

const App: React.FC = () => {
  const [entries, setEntries] = useState<ProfitEntry[]>(() => {
    const saved = localStorage.getItem('team_profits');
    return saved ? JSON.parse(saved) : [];
  });
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [aiAnalysis, setAiAnalysis] = useState<string>('');
  const [isAnalyzing, setIsAnalyzing] = useState(false);

  useEffect(() => {
    localStorage.setItem('team_profits', JSON.stringify(entries));
  }, [entries]);

  const stats = useMemo<SummaryStats>(() => {
    return entries.reduce((acc, curr) => ({
      totalRevenue: acc.totalRevenue + curr.amount,
      totalWorkerPayouts: acc.totalWorkerPayouts + curr.totalPayout,
      totalMentorPayouts: acc.totalMentorPayouts + curr.mentorAmount,
      totalIrlShare: acc.totalIrlShare + curr.finalIrlShare,
      totalEntries: acc.totalEntries + 1
    }), {
      totalRevenue: 0,
      totalWorkerPayouts: 0,
      totalMentorPayouts: 0,
      totalIrlShare: 0,
      totalEntries: 0
    });
  }, [entries]);

  const handleAddEntry = (entry: ProfitEntry) => {
    setEntries(prev => [entry, ...prev]);
  };

  const handleDeleteEntry = (id: string) => {
    if (window.confirm('Вы уверены, что хотите удалить эту запись?')) {
      setEntries(prev => prev.filter(e => e.id !== id));
    }
  };

  const runAnalysis = async () => {
    setIsAnalyzing(true);
    const analysis = await analyzeTeamPerformance(entries);
    setAiAnalysis(analysis);
    setIsAnalyzing(false);
  };

  return (
    <div className="min-h-screen p-4 md:p-8 max-w-[1600px] mx-auto space-y-8">
      {/* Header */}
      <header className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 border-b border-slate-800 pb-6">
        <div>
          <h1 className="text-3xl font-extrabold tracking-tight text-white flex items-center">
            <span className="bg-blue-600 p-2 rounded-lg mr-3 shadow-lg">📈</span>
            Team Profit Ledger
          </h1>
          <p className="text-slate-400 mt-1 font-medium">Управление профитами Telegram команды</p>
        </div>
        <div className="flex items-center space-x-3">
          <button 
            onClick={() => setIsFormOpen(true)}
            className="bg-emerald-600 hover:bg-emerald-500 text-white font-bold py-2.5 px-6 rounded-lg transition-all shadow-lg active:scale-95"
          >
            + Добавить Профит
          </button>
        </div>
      </header>

      {/* Stats Dashboard */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
        <StatCard title="Общая Выручка" value={`$${stats.totalRevenue.toLocaleString()}`} icon="💰" color="text-emerald-400" />
        <StatCard title="Выплачено Воркерам" value={`$${stats.totalWorkerPayouts.toLocaleString()}`} icon="👷" color="text-blue-400" />
        <StatCard title="Доля IRL (Net)" value={`$${stats.totalIrlShare.toLocaleString()}`} icon="🏛️" color="text-indigo-400" />
        <StatCard title="Комиссии Наставников" value={`$${stats.totalMentorPayouts.toLocaleString()}`} icon="🎓" color="text-purple-400" />
      </div>

      {/* Main Content Area */}
      <div className="grid grid-cols-1 xl:grid-cols-4 gap-6">
        <div className="xl:col-span-3 space-y-4">
          <div className="flex justify-between items-center">
            <h2 className="text-xl font-bold text-slate-200">Таблица транзакций</h2>
            <span className="text-xs bg-slate-800 text-slate-400 px-3 py-1 rounded-full uppercase tracking-widest font-bold">
              {stats.totalEntries} записей
            </span>
          </div>
          <ProfitTable entries={entries} onDelete={handleDeleteEntry} onUpdate={() => {}} />
        </div>

        {/* Sidebar / AI Analysis */}
        <aside className="space-y-6">
          <div className="bg-slate-900 border border-slate-700 rounded-xl p-6 shadow-xl relative overflow-hidden">
             <div className="absolute top-0 right-0 p-2 text-3xl opacity-10 select-none pointer-events-none">✨</div>
             <h3 className="text-lg font-bold text-white mb-4 flex items-center">
               <span className="mr-2">🤖</span> AI Performance Insights
             </h3>
             {aiAnalysis ? (
               <div className="text-sm text-slate-300 leading-relaxed bg-slate-800/50 p-4 rounded-lg border border-slate-700">
                 {aiAnalysis}
               </div>
             ) : (
               <div className="text-center py-6">
                 <p className="text-slate-500 text-sm mb-4">Нажмите кнопку для анализа производительности команды с помощью Gemini AI.</p>
               </div>
             )}
             <button 
                onClick={runAnalysis}
                disabled={isAnalyzing || entries.length === 0}
                className={`w-full mt-4 py-2.5 rounded-lg font-bold text-sm transition-all flex items-center justify-center
                  ${isAnalyzing ? 'bg-slate-700 text-slate-500' : 'bg-gradient-to-r from-blue-600 to-indigo-600 hover:from-blue-500 hover:to-indigo-500 text-white shadow-lg'}
                  disabled:opacity-50 disabled:cursor-not-allowed`}
             >
               {isAnalyzing ? (
                 <>
                   <span className="animate-spin mr-2">⟳</span> Анализирую...
                 </>
               ) : 'Запустить AI Анализ'}
             </button>
          </div>

          <div className="bg-slate-900/50 border border-slate-800 rounded-xl p-6">
            <h4 className="text-sm font-bold text-slate-400 uppercase tracking-widest mb-4">Быстрые советы</h4>
            <ul className="text-xs text-slate-500 space-y-3">
              <li className="flex items-start">
                <span className="mr-2 text-blue-500">•</span>
                <span>Используйте ники TG через @ для удобства поиска.</span>
              </li>
              <li className="flex items-start">
                <span className="mr-2 text-blue-500">•</span>
                <span>Доля IRL включает в себя комиссию команды и налоги.</span>
              </li>
              <li className="flex items-start">
                <span className="mr-2 text-blue-500">•</span>
                <span>Сумма наставника вычитается из чистой доли воркера.</span>
              </li>
            </ul>
          </div>
        </aside>
      </div>

      {isFormOpen && (
        <ProfitForm 
          onAdd={handleAddEntry}
          onClose={() => setIsFormOpen(false)}
        />
      )}

      <footer className="text-center pt-8 pb-12 text-slate-600 text-xs">
        <p>© 2024 Team Profit Ledger • Построено для профессиональных команд</p>
      </footer>
    </div>
  );
};

const StatCard: React.FC<{ title: string; value: string; icon: string; color: string }> = ({ title, value, icon, color }) => (
  <div className="bg-slate-900 border border-slate-800 rounded-xl p-5 shadow-lg hover:border-slate-700 transition-colors">
    <div className="flex items-center justify-between mb-2">
      <span className="text-slate-400 text-sm font-bold">{title}</span>
      <span className="text-xl">{icon}</span>
    </div>
    <div className={`text-2xl font-black ${color}`}>{value}</div>
  </div>
);

export default App;

