import React, { useState, useEffect } from 'react';
import { ProfitEntry } from '../types';

interface ProfitFormProps {
  onAdd: (entry: ProfitEntry) => void;
  onClose: () => void;
}

export const ProfitForm: React.FC<ProfitFormProps> = ({ onAdd, onClose }) => {
  const [formData, setFormData] = useState<Omit<ProfitEntry, 'id' | 'workerShare' | 'irlShare' | 'mentorAmount' | 'totalPayout' | 'finalIrlShare'>>({
    worker: '',
    direction: '',
    stage: 'Pending',
    amount: 0,
    percentage: 70,
    country: '',
    payoutStatus: 'Pending',
    date: new Date().toISOString().split('T')[0],
    mentor: '',
    mentorPercentage: 10,
    referralStatus: false,
    referralAmount: 0,
  });

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value, type } = e.target;
    const val = type === 'checkbox' ? (e.target as HTMLInputElement).checked : value;
    setFormData(prev => ({
      ...prev,
      [name]: type === 'number' ? parseFloat(value) || 0 : val
    }));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    // Calculations
    const workerShareRaw = (formData.amount * formData.percentage) / 100;
    const irlShareRaw = formData.amount - workerShareRaw;

    // Mentor logic: Mentor share is only calculated if a mentor name is provided
    const hasMentor = formData.mentor && formData.mentor.trim() !== '';
    const mentorAmt = hasMentor ? (workerShareRaw * formData.mentorPercentage) / 100 : 0;

    const referralAmt = formData.referralStatus ? formData.referralAmount : 0;

    // Total worker payout is their share minus mentor commission and referral fees
    const totalPay = workerShareRaw - mentorAmt - referralAmt;

    // Final IRL share includes the original irl share plus all deducted fees
    const finalIrl = irlShareRaw + mentorAmt + referralAmt;

    const newEntry: ProfitEntry = {
      ...formData,
      mentor: hasMentor ? formData.mentor : '', // Clean up empty strings
      id: Math.random().toString(36).substr(2, 9),
      workerShare: workerShareRaw,
      irlShare: irlShareRaw,
      mentorAmount: mentorAmt,
      totalPayout: totalPay,
      finalIrlShare: finalIrl
    };

    onAdd(newEntry);
    onClose();
  };

  const hasMentor = formData.mentor && formData.mentor.trim() !== '';

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm p-4">
      <div className="bg-slate-900 border border-slate-700 rounded-xl w-full max-w-2xl shadow-2xl overflow-hidden">
        <div className="bg-slate-800 px-6 py-4 flex justify-between items-center border-b border-slate-700">
          <h2 className="text-xl font-bold text-white">Добавить новый профит</h2>
          <button onClick={onClose} className="text-slate-400 hover:text-white transition-colors text-2xl">&times;</button>
        </div>

        <form onSubmit={handleSubmit} className="p-6 grid grid-cols-1 md:grid-cols-2 gap-4 max-h-[80vh] overflow-y-auto custom-scrollbar">
          <div className="space-y-1">
            <label className="text-xs font-semibold text-slate-400 uppercase">Воркер (TG)</label>
            <input name="worker" required value={formData.worker} onChange={handleChange} className="w-full bg-slate-800 border border-slate-700 rounded p-2 focus:ring-2 focus:ring-blue-500 outline-none text-white" placeholder="nick_tg" />
          </div>

          <div className="space-y-1">
